INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bionic Heart', 'London, 2099. The earth isn''t what it used to be anymore. Incredible climate changes have corrupted the weather, causing a permanent rain on most of the Earth''s surface. You play the role of Luke Black, a 36-year-old bio-informatic engineer. He is one of the lead programmers at Nanotech, a big nanotechnology research company. But one night, his life is changed forever when he encounters Tanya. Who is she? What does she wants from Luke?' FROM games WHERE igdb_id = 9782 ON CONFLICT (game_id, language_code) DO NOTHING;
