INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flock!', 'Protect your cornfields and lock up your livestock, because Flock! is here! Pilot a UFO around vibrantly-colored landscapes in this charming sandbox puzzle game where you must herd animal life back to the Motherflocker. Using a powerful physics engine that drives many of the game’s elements, Flock! features over 50 pastoral puzzles. Pick up wood to form bridges, move boulders to create obstructions, and flatten fields into pathways all to help deliver your herd before time runs out! Flock together with a friend and even create and share your own crazy levels online.' FROM games WHERE igdb_id = 14929 ON CONFLICT (game_id, language_code) DO NOTHING;
