INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Axel & Pixel', 'Axel and Pixel are trapped in a beautiful but dangerous dream world. If they plan to get out they must solve its mysteries. Drawn by hand and rendered in full high-definition, Axel & Pixel is a unique journey through an artist''s dream. Axel and Pixel features 24 stunning chapters set in 4 different seasons, 3 vehicle minigames and many challenging puzzles.' FROM games WHERE igdb_id = 14845 ON CONFLICT (game_id, language_code) DO NOTHING;
