INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hero of Sparta', 'Take up the fiercest challenge and fight from the Oracle''s island to the summit of Olympus. Hero of Sparta features an innovative double-view system combining absolute action and platforming. Face legions of enemies across eight levels of action, with the most impressive mythical creatures standing in your path -- Cerberus, the Colossus, etc. Upgrade your equipment to gain the the Chronos Sword, the Medusa Shield, and more.' FROM games WHERE igdb_id = 21690 ON CONFLICT (game_id, language_code) DO NOTHING;
