INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball: Revenge of King Piccolo', 'Heading back to the early days of the Dragon Ball story, players control Kid Goku as he sets out on fantastic adventures with his friends. The title faithfully reproduces the uniqueness and special humour of the early Dragon Ball series, while adding an original blend of action and adventure to the mix. With the original Japanese music and voiceover included for maximum authenticity, Dragon Ball: Revenge of King Piccolo offers fans a dazzling new experience with the characters and universe they know and love.' FROM games WHERE igdb_id = 19309 ON CONFLICT (game_id, language_code) DO NOTHING;
