INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Halo Wars', 'The Covenant has declared war on humanity, and Harvest is the first battleground. Set 21 years before the events of Halo: Combat Evolved, Halo Wars is an exciting real-time strategy game set in the legendary Halo universe. In this unique installment in the Halo franchise, players experience the epic battles that marked the beginning of the Covenant War. With the UNSC Spirit of Fire at their disposal, players fight in the intense and enormous conflicts that would define humanity''s relentless heroism in its darkest hour.' FROM games WHERE igdb_id = 988 ON CONFLICT (game_id, language_code) DO NOTHING;
