INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Banjo-Tooie', 'The Xbox 360 remaster of Banjo-Tooie has visual and performance improvements over the Nintendo 64 version. In this version, the player doesn''t loose the notes after getting out of a stage, which is a major difference over the original, since it doesn''t require the player to get everything again after leaving or dying. It also has a reimplementation of the Stop ''n'' Swop feature, using the save data from the Banjo-Kazooie remaster to unlock new content.' FROM games WHERE igdb_id = 201645 ON CONFLICT (game_id, language_code) DO NOTHING;
