INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tunnel Rats', 'Tunnel Rats is a dark and intense single-player shooter for PC that depicts the horrific realities of the Vietnam War as seen through the eyes of a young US soldier. As member of a "Tunnel Rats" squad, the player is trained to clearing out the huge tunnel systems underneath the jungle of Vietnam.' FROM games WHERE igdb_id = 15996 ON CONFLICT (game_id, language_code) DO NOTHING;
