INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cartoon-network-universe-fusionfall', 2811, '2009-01-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coawgx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsdaq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cartoon Network Universe: FusionFall', 'FusionFall is a free-to-play MMOG that takes all of the best Cartoon Network characters, re-imagines them in an anime-inspired style and sets them in dynamic new environments. Players create their own in-game avatars and battle alongside their favorite cartoon characters to save the world from an epic alien invasion. Players team up with friends and more than 50 characters from some of Cartoon Network’s most popular shows, including Ben 10 Alien Force, Dexter’s Laboratory, Foster’s Home for Imaginary Friends, Ed, Edd’ n Eddy, The Powerpuff Girls, Kids Next Door, Samurai Jack, and many more, to restore order to the Cartoon Network universe.' FROM games WHERE igdb_id = 2811 ON CONFLICT (game_id, language_code) DO NOTHING;
