INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('academy-of-champions-soccer', 4657, '2009-09-04', 74, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9pnz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/dt33bpfmdnzt9lomlnk2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Academy of Champions: Soccer', 'Academy Of Champions: Soccer features a story mode set at a magical soccer academy, in which the player must build a group of five players to challenge other teams. Academy of Champions features arcade-style soccer, focusing on tricks, shooting, and the whimsical nature of the academy. Academy of Champions has a main story mode and a supplemental quick-play mode to allow the user to play a single match by themselves or with a friend. The story mode takes place at Brightfield Academy, a magical soccer academy featuring Pelé and Mia Hamm in cartoon form as the masters of the academy.' FROM games WHERE igdb_id = 4657 ON CONFLICT (game_id, language_code) DO NOTHING;
