INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Transformers: Revenge of the Fallen', 'Transformers: Revenge of the Fallen is set a few years after the defeat of Megatron in the first game. The game is a linear third-person shooter that puts the player in control of many of the main characters from the movie, shifting between both Autobot and Decepticon factions.' FROM games WHERE igdb_id = 7471 ON CONFLICT (game_id, language_code) DO NOTHING;
