INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ea-sports-active', 4826, '2009-05-19', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co74tc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/jt6qbxqlit8cn3iydfqm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'EA Sports Active', 'EA SPORTS Active tracks your movements on screen to give you real time feedback on your workout. Track both upper and lower body movements and experience Wii controls in a whole new way with our specially designed leg strap. Embark on the 30 Day Challenge and use the structure as a road map to reach your goals. Your trainer will be the focal point of the experience and create a new minute workout for you every day, providing clear instruction, motivation and positive encouragement. EA SPORTS Active features a wide variety of activities that target upper body, lower body, as well as cardio. Each daily workout will feel different then the last and increase in intensity as you work up a sweat towards your goals. In the custom workout mode, you can cater the length of the workout to the time you have available, which body areas you want to focus on and identify your favorite of the over 20 exercises – and you will see how many calories you are burning in real time. EA SPORTS Active gives you the benefit of a personal trainer right into your living room and the promise of a better you.' FROM games WHERE igdb_id = 4826 ON CONFLICT (game_id, language_code) DO NOTHING;
