INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Hisoutensoku: Choudokyuu Ginyoru no Nazo wo Oe', 'Touhou Hisoutensoku: Choudokyuu Ginyoru no Nazo wo Oe is a standalone expansion pack to the fighting spinoff Scarlet Weather Rhapsody with five new characters, first released by Tasogare Frontier at Comiket 76. Combining this expansion with an installation of Scarlet Weather Rhapsody allows for the use of additional Touhou characters within the new expansion. Like its predecessors, Immaterial and Missing Power and Scarlet Weather Rhapsody, Touhou Hisoutensoku is a collaboration between ZUN and Tasogare Frontier. Tasogare Frontier is well-known for games such as Eternal Fighter Zero, Immaterial and Missing Power and Scarlet Weather Rhapsody.' FROM games WHERE igdb_id = 27157 ON CONFLICT (game_id, language_code) DO NOTHING;
