INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WarioWare D.I.Y.', 'This game, which puts the concept of user-generated content on center stage, allows players to design their own micro-games from scratch. Every element, such as the characters, the environment, the actions and even the purpose of the micro-game itself, is controlled entirely by the player. Players will then be able to share their completed micro-games with other WarioWare D.I.Y. owners.' FROM games WHERE igdb_id = 1708 ON CONFLICT (game_id, language_code) DO NOTHING;
