INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trine', 'Trine is a physics-based action game where three characters allow clever solutions to challenges created by hazardous puzzles and threatening enemies. The gameplay is based on fully interactive physics – each character''s different abilities and tactics can be used to invent new ways to overcome obstacles and save the kingdom.' FROM games WHERE igdb_id = 6247 ON CONFLICT (game_id, language_code) DO NOTHING;
