INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mirror''s Edge', 'Mirror''s Edge is a side-scrolling platform game developed by IronMonkey Studios and published by Electronic Arts. It was released for the iPod on September 2, 2009, for iPad and iPhone on April 1, 2010, and later for Windows Phone on July 13, 2012. The game is a prequel to the original Mirror''s Edge, setting the scene about Runners and the city''s shady corporations.' FROM games WHERE igdb_id = 77348 ON CONFLICT (game_id, language_code) DO NOTHING;
