INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fight Night Round 4', 'Fight Night Round 4 is a boxing video game developed by EA Sports. It is the sequel to Fight Night Round 3, released in 2006. It was released on June 25, 2009 in North America and on June 26, 2009 in Europe, for the PlayStation 3 and Xbox 360.[3] The game''s featured boxers are Muhammad Ali and Mike Tyson.[4] It contains 48 licensed boxers[5] as well as several new modes, such as Legacy mode.[6][7]' FROM games WHERE igdb_id = 6993 ON CONFLICT (game_id, language_code) DO NOTHING;
