INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'This is the Only Level', 'The elephant forgot the rest of the levels, but luckily he still has one left! Help him beat it in all his metagaming glory. Use your keen knowledge of gaming and dexterity to manhandle your way through a variety of challenges. Get your mind out of the box for once! Take it outside for a walk, or maybe grab a bite to eat with it.' FROM games WHERE igdb_id = 121726 ON CONFLICT (game_id, language_code) DO NOTHING;
