INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Call of Juarez: Bound In Blood', 'In the remote and deadly Wild West, the outlaw McCall brothers are on a quest for the legendary Gold of Juarez. In their journey across a vast landscape, these lawless gunslingers will stop at nothing to achieve their goal. Arm yourself with pistols, cannons, machine guns and more as you strike out on a mission with two fearless compatriots whose bonds of blood are only strengthened by the blood they spill together.' FROM games WHERE igdb_id = 430 ON CONFLICT (game_id, language_code) DO NOTHING;
