INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('art-style-boxlife', 47826, '2009-02-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobbv6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/bw6mi68ovt6vhz4okmvn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Art Style: Boxlife', 'Cut paper into various shapes and create as many boxes as possible within the time limit to earn rewards! Climb the corporate ladder in the world of BOXLIFE using your wits and… paper? Use the Nintendo DSi Stylus to cut and then manipulate the paper into a box shape. Be careful though: if you’re not efficient with your cuts, you’ll waste paper and be penalized. R&D mode teaches you new patterns and then challenges you to complete various ranks, while FACTORY mode gives you the chance to earn money by making as many boxes as possible from an endless sheet of paper. Success in each mode brings its own reward: clear ranks to be promoted and change your character’s appearance and use your earnings to acquire new items for your character’s miniature garden. With its stylish graphics and catchy sound, you may just find that thinking inside the box isn’t such a bad thing sometimes!Games in the Art Style series feature elegant design, polished graphics, and pick-up-and-play controls, creating an experience focused purely on fun and engaging game play.' FROM games WHERE igdb_id = 47826 ON CONFLICT (game_id, language_code) DO NOTHING;
