INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Military Madness: Nectaris', 'Military Madness: Nectaris is a 3D remake of the original Military Madness. The Military is back for a new generation of recruits! The classic turn-based strategy series Military Madness, a.k.a. Nectaris, is exploding onto WiiWare, PSN and Xbox Live Arcade with a platoon of new features. Coordinate strategies or taunt foes in team or vs. multiplayer modes for up to 4 people, offline or online. Customise the all-new commander unit by selecting from 20 unique abilities as it leads your forces in multiplayer. Command respect as you increase your rank as you march up the leaderboards on your mission to prove you’re the top general around. This is the maddest game in the series yet!' FROM games WHERE igdb_id = 20505 ON CONFLICT (game_id, language_code) DO NOTHING;
