INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Quest Wars', 'Dragon Quest Wars is a turn-based strategy game played out across a number of quick and challenging rounds. The player will pick four monster playing pieces to battle on their team, with Dragon Quest superstars Slime, Dracky, Hammerhood, Healslime, Chimaera and Golem all available to choose from. Played across a table-top style arena the ultimate aim of the game is to battle and defend against the opposing team to advance to the other side of the arena.' FROM games WHERE igdb_id = 1825 ON CONFLICT (game_id, language_code) DO NOTHING;
