INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'XG Blast!', 'XG Blast! is an arcade shooter delivered in a bright and colorful retro style. Players control the spaceship Aknathen, which wandered into hostile territory during a secret experimental journey to test the spaceship''s capabilities and advanced devices. Utilize the unique powers of your ship as you fight countless squadrons of enemy ships. It is up to you to get your crew back in one piece and save your people from annihilation!' FROM games WHERE igdb_id = 21254 ON CONFLICT (game_id, language_code) DO NOTHING;
