INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('space-invaders-infinity-gene', 22988, '2009-07-27', 77, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2h1u.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3bga.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Invaders: Infinity Gene', 'Space Invaders, the game that defined video games for generations, is back with a new twist! The game starts off looking like the classic Space Invaders, but as you play through the game, it evolves. Unlock new stages, new power ups, and new features. The full game features a total of 133 stages from both Normal Mode and the breathtaking Challenge Mode where stages change with each playthrough. You can even blast your way through unique stages evolved from your very own music! Compete against other players from all around the world in real time with the appropriately named Real Time Rankings! Space Invaders Infinity Gene is the pinnacle of outer space shooting action! The more you play, the more the game evolves!' FROM games WHERE igdb_id = 22988 ON CONFLICT (game_id, language_code) DO NOTHING;
