INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('astro-boy-the-video-game', 4682, '2009-10-08', 43, 'https://images.igdb.com/igdb/image/upload/t_cover_big/idsldgimt7if1aaitezx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/cvpwicfysdztezawhwd5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astro Boy: The Video Game', 'Become the iconic hero, Astro Boy, and take to the streets and skies on an epic adventure to save Metro City from the clutches of the evil President Stone and his robot army. Utilizing Astro''s entire arsenal of iconic weapons and abilities -- Finger Lasers, Arm Cannon, Butt Machine Guns and Drill Attacks, players will battle hordes of robot enemies and colossal bosses including some never-before-seen enemies across Metro City and the mysterious Surface. Using an intuitive combat system that adds depth to gameplay, players will experience classic platform action and exhilarating flight combat levels as they use Astro''s unique rocket boosters to hover, avoid enemies and zip out of the way of danger. Astro Boy offers numerous unlockable and collectible elements that include exclusive art work, different versions of Astro Boy and more, as players live the story solo or side by side with a friend in 2 player co-op mode on PlayStation 2.' FROM games WHERE igdb_id = 4682 ON CONFLICT (game_id, language_code) DO NOTHING;
