INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Rising: Chop Till You Drop', 'Dead Rising: Chop Till you Drop is an adaptation of Dead Rising, for the Wii. The freelance photojournalist Frank West investigates a zombie outbreak in Willamette, Colorado. He has three days at the mall to rescue survivors and solve the case before the helicopter that dropped him off returns. The basic outlines are maintained from the Xbox 360 game, but numerous changes have been made to fit the game into the Resident Evil 4 engine and to accommodate the Wii''s graphical capabilities and very different controller.' FROM games WHERE igdb_id = 4798 ON CONFLICT (game_id, language_code) DO NOTHING;
