INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wet', 'Wet is an action game that combines shooting and swordplay with acrobatics and gore. The main character, Rubi, carries twin pistols and a sword (she can also carry dual shotguns, submachine guns, or crossbows), and can fire while jumping, sliding on her knees, and running on walls. During these acrobatic actions, the game enters slow motion, and she will automatically aim at a second enemy, allowing the player to shoot at two enemies at once. She can also combine her attacks, such as wall running off a person or performing a sword uppercut while sliding.' FROM games WHERE igdb_id = 3057 ON CONFLICT (game_id, language_code) DO NOTHING;
