INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castlevania: The Adventure ReBirth', 'The classic Castlevania game is reborn for the Wii with all-new upgrades. Another 100 years has passed since the death of Count Dracula, but the revival of his curse has emerged once again within the realms of Transylvania. Play the role of the ultimate gothic hero from the long lineage of vampire hunters, the Belmont clan, and rid the universe of Dracula’s legion of darkness and doom. Based on the classic 1989 original Castlevania: The Adventure, the WiiWare version will allow players of a new generation and older fans to experience one of the most popular games within the storied Castlevania timeline from a new perspective.' FROM games WHERE igdb_id = 1146 ON CONFLICT (game_id, language_code) DO NOTHING;
