INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Henry Hatsworth in the Puzzling Adventure', 'In Henry Hatsworth in the Puzzling Adventure players embark on single player fun like no other. Here Henry Hatsworth, a quirky, lighthearted character serves as your guide on a journey through a new style of gaming on your Nintendo DS that combines the action of an adventure game with the challenge of a puzzle game. In this two-in-one extravaganza players explore five exotic worlds, fight a variety of opponents, and venture through more than 30 levels, including nearly a dozen hidden levels while taking on outrageous world-ending bosses.' FROM games WHERE igdb_id = 9601 ON CONFLICT (game_id, language_code) DO NOTHING;
