INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy: Crystal Chronicles - Echoes of Time', 'Final Fantasy Crystal Chronicles: Echoes of Time is an installment in the Final Fantasy Crystal Chronicles series. It is the first Final Fantasy Crystal Chronicles game that allows players to play together online and it allows players who own a Nintendo Wii or Nintendo DS to play together at the same time using the Pollux Engine, an Engine created by Square Enix.' FROM games WHERE igdb_id = 23016 ON CONFLICT (game_id, language_code) DO NOTHING;
