INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bayonetta', 'A member of an ancient witch clan and possessing powers beyond the comprehension of mere mortals, Bayonetta faces-off against countless angelic enemies, many reaching epic proportions, in a game of 100% pure, unadulterated all-out action. Outlandish finishing moves are performed with balletic grace as Bayonetta flows from one fight to another. With magnificent over-the-top action taking place in stages that are a veritable theme park of exciting attractions, Bayonetta pushes the limits of the action genre, bringing to life its fast-paced, dynamic climax combat.' FROM games WHERE igdb_id = 2136 ON CONFLICT (game_id, language_code) DO NOTHING;
