INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA Live 10', 'NBA Live 10 is the 2009 installment in the NBA Live series, developed by EA Canada and published by Electronic Arts. Dwight Howard of the Orlando Magic is the cover athlete. It was released in 2009 for PlayStation 3, Xbox 360, PSP and iOS (the latter under the title NBA Live by EA Sports).[1] NBA Live 10 was to be followed by NBA Live 13 which was cancelled in late 2012. NBA Live 10 was the last game in the NBA Live series for 4 years until NBA Live 14 in 2013.' FROM games WHERE igdb_id = 7107 ON CONFLICT (game_id, language_code) DO NOTHING;
