INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bookworm-adventures-volume-2', 15714, '2009-06-04', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1z1h.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qgzjub552o6kpys60d18.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bookworm Adventures Volume 2', 'Stop the presses! The walls of fiction are collapsing as characters run wild through the Great Library, and only Lex the Bookworm can save the world from certain doom! Build words and battle monsters to survive three storybooks with 10 chapters each. Trade barbs, banter and body blows with over 130 foes, and earn help from fighting friends along the way! The better the word, the badder the damage — so advance your word power with over 20 powerful treasures, including all-new Rainbow tiles. And when you''ve conquered Adventure mode, the fun keeps going: work wordy wonders in three extra game modes and flex your lexicon in six mini-games.' FROM games WHERE igdb_id = 15714 ON CONFLICT (game_id, language_code) DO NOTHING;
