INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Beatles: Rock Band', 'The Beatles: Rock Band is a 2009 music video game. It is the third major console release in the Rock Band music video game series, in which players can simulate the playing of rock music by using controllers shaped like musical instruments. The Beatles: Rock Band is the first band-centric game in the series, and it is centered on the popular English rock group the Beatles. The game features virtual portrayals of the four band members performing the songs throughout the band''s history, including depictions of some of their famous live performances, as well as a number of "dreamscape" sequences for songs from the Abbey Road Studios recording sessions during the group''s studio years.' FROM games WHERE igdb_id = 2693 ON CONFLICT (game_id, language_code) DO NOTHING;
