INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Space: Extraction', 'Dead Space Extraction tells the untold story of the Aegis VII Colony through a handful of survivors battling to reach the orbiting USG Ishimura amidst a horrific infection and the initial invasion by a violent alien race known as Necromorphs. As these survivors'' allies mysteriously fall victim to dementia, it becomes clear that protecting a young girl granting them a bizarre immunity may be their only hope for survival in a struggle that could have implications for all of humanity.' FROM games WHERE igdb_id = 985 ON CONFLICT (game_id, language_code) DO NOTHING;
