INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ace Attorney Investigations: Miles Edgeworth', 'Ace Attorney Investigations: Miles Edgeworth is a 2009 adventure video game developed and published by Capcom. It was originally released for the Nintendo DS in Japan in 2009, and internationally in 2010, and later for iOS and Android in 2017. It is the fifth game in the Ace Attorney series, and is set between the events of the third and fourth games, Phoenix Wright: Ace Attorney − Trials and Tribulations and Apollo Justice: Ace Attorney.' FROM games WHERE igdb_id = 1430 ON CONFLICT (game_id, language_code) DO NOTHING;
