INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aztaka', 'Inspired by Aztec legend, this action/rpg side-scroller will casts you into the middle of a war between the Gods and Mankind. As Huitzilo, heir of the Sun God, skilled in both the arts of combat and magic, only you can save your people from the wrath of the Aztec Gods by reuniting the seven phonograms. Accompanied by your faithful companion Ayopha - trapped in the form of a hummingbird by a magical curse – you will overcome the obstacles in you path through a combination of fighting prowess and spiritual magic.' FROM games WHERE igdb_id = 16067 ON CONFLICT (game_id, language_code) DO NOTHING;
