INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fatale', 'Salome was a first century Judean princess mentioned in the Christian Bible by Matthew and by Mark. But it is Oscar Wilde''s 19th century play Salome that really inspired Fatale. In the Bible, Salome is a child who dances for King Herod and asks the head of John the Baptist as a reward. In Wilde''s version, Salome falls in love with the prophet. He rejects her and she has him executed. The play ends with her kissing the lips of his decapitated head.' FROM games WHERE igdb_id = 15989 ON CONFLICT (game_id, language_code) DO NOTHING;
