INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Angry Birds', 'Angry Birds is a 2009 physics-based casual puzzle video game developed by Finnish video game developer Rovio Entertainment. Players control a flock of multi-colored birds on a mission to rescue their eggs from green-colored pigs. Using a slingshot, they launch the birds at these pigs stationed in or around different structures. The goal is to eliminate all the pigs on each level with a limited number of birds.' FROM games WHERE igdb_id = 2035 ON CONFLICT (game_id, language_code) DO NOTHING;
