INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('moon', 21898, '2009-02-13', 77, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1v3f.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc5koc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moon', 'Set on the Earth’s moon in the mid-21st century, in Moon, players take on the role of Major Kane. Chief of Military Operations for the Extra Terrestrial Encounter Organization (ETEO), you and your team have been brought in to investigate a series of strange happenings. Ever since the Roswell incident it has been clear that Earth has been visited by other beings, now a hundred years later it would seem that something similar may be happening on the moon. Contact with a distant lunar outpost was lost shortly after they reported discovery of a ‘hatch’ of alien origin during a routine excavation. What follows could be the next giant leap forward for mankind, but just what are we stepping into? Whatever it is, erratic energy readings from deep below the lunar surface has you thinking that it will not be a diplomatic mission. Welcome to the Moon Major.' FROM games WHERE igdb_id = 21898 ON CONFLICT (game_id, language_code) DO NOTHING;
