INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Warriors: Street Brawl', 'Warriors ... come out to play-ayyy! Relive the unforgettable cult classic movie and experience The Warriors: Street Brawl in a 3-D side-scrolling fight fest. Brawl it out old school style using your fists and a variety of weapons. Battle through 20 miles of gang-infested Manhattan in order to get back to your home turf, Coney Island. Play as Swan, Cochise, Vermin, or Rembrandt and lead your gang all the way to the showdown against Luther and the Rogues.' FROM games WHERE igdb_id = 21218 ON CONFLICT (game_id, language_code) DO NOTHING;
