INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy: The 4 Heroes of Light', 'With FINAL FANTASY: The 4 Heroes of Light, the FINAL FANTASY series is rendered anew as an epic storybook adventure by the creators of the FINAL FANTASY III and FINAL FANTASY IV Nintendo DS remakes. Players will enter a beautiful fairy-tale world featuring illustrations and character designs by acclaimed character designer Akihiko Yoshida (FINAL FANTASY III for DS, FINAL FANTASY XII).' FROM games WHERE igdb_id = 17463 ON CONFLICT (game_id, language_code) DO NOTHING;
