INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Real Warfare 1242', 'Real Warfare: 1242, is a realistic real-time strategy game based on authentic historic events. It invites you to experience the glorious times of princes, knights and vast battles. The player''s goal is to direct Alexander Nevsky through meticulously recreated historic battlegrounds and achieve the greatest of victories by repelling the attacks of Teutonic and Swedish knights, bringing Lithuania to peace and eliminating every single invader in 1242.' FROM games WHERE igdb_id = 9856 ON CONFLICT (game_id, language_code) DO NOTHING;
