INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('spectrobes-origins', 5173, '2009-08-18', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co27rc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/l4fsdea2wdag0fafto2l.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spectrobes: Origins', 'Spectrobes mixes monster battling with a real-time action RPG experience, so you''ll not only be managing which critter is out on the field and attacking, but also running your main character around and participating in combat the feels like a mix between classic action battle mechanics and something like Monster Hunter lite. Different weapons allow the human leads to change up styles and elemental attacks, so you can have a leaf-based blade, an electric gauntlet, ranged cannon weapons and heavier bashing melee attacks. As you progress through the game not only will your Spectrobes gain levels, but your humans will as well. It''s a constant balance of progressing not only your main character, but also all of your monsters too. Tie in a search and excavate system for finding new fossils with new Spectrobes and you''ve got a mechanic that is addicting enough to keep the experience moving; even if the levels themselves aren''t always the most inspired areas to trek through.' FROM games WHERE igdb_id = 5173 ON CONFLICT (game_id, language_code) DO NOTHING;
