INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Call of Duty: Modern Warfare 2', 'Call of Duty: Modern Warfare 2 is a first-person shooter video game developed by Infinity Ward and published by Activision for the Xbox 360 and PlayStation 3 video game consoles and the Microsoft Windows operating system. Officially announced on February 11, 2009, the game was released worldwide on November 10, 2009. It is the sixth installment of the Call of Duty series and the direct sequel to Call of Duty 4: Modern Warfare, continuing the same storyline, with Call of Duty: Modern Warfare 3 set to end the storyline.' FROM games WHERE igdb_id = 559 ON CONFLICT (game_id, language_code) DO NOTHING;
