INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grey''s Anatomy: The Video Game', 'Play as all your favorite characters and perform life-or-death operations in this all-new Grey''s Anatomy story. Immerse yourself for the first time in this all-new Grey''s Anatomy story written in collaboration with the TV show writers. Play as your favorite characters as you strive to save Seattle Grace Hospital from its worst crisis yet. Influence the outcome of the storyline and perform all the multi-step surgeries that the series is known for.' FROM games WHERE igdb_id = 4897 ON CONFLICT (game_id, language_code) DO NOTHING;
