INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ice-age-dawn-of-the-dinosaurs', 4923, '2009-06-30', 100, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ddn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/schfw4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ice Age: Dawn of the Dinosaurs', 'Based on the computer-animated movie starring the voices of Ray Romano and John Leguizamo, Ice Age: Dawn of the Dinosaurs is a 3D platform game that has you controlling multiple prehistoric protagonists across more than 15 levels of lighthearted action. Help Manny, Sid, Diego, Scrat, and friends navigate their way through the lush jungles of a world lurking underneath the ice: a tropical world inhabited by dinosaurs. Master each character''s distinct moves while exploring caves, riding a pterodactyl, avoiding a rampaging Tyrannosaurus rex, running atop a ball of ice, and more. Those having difficulty during certain sequences can receive tips from woolly mammoth Ellie as well as possums Crash and Eddie. In addition to the single-player campaign, Ice Age 2 offers eight competitive mini-games supporting up to four players.' FROM games WHERE igdb_id = 4923 ON CONFLICT (game_id, language_code) DO NOTHING;
