INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('overlord-minions', 48, '2009-06-23', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co290u.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/imqioz7qhb49zjl2ambu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Overlord: Minions', 'Meet Giblet, Blaze, Stench, and Zap - an elite Minion crew who, assisted by minion master Gnarl, get star billing in Overlord Minions, an irresistible and accessible puzzle action game, designed exclusively for Nintendo DS. In Overlord Minions, the Overlord commands the Minion team remotely. The Nintendo DS stylus becomes an extension of his evil will and every precise Touch Screen command is the player-as-Overlord directing, commanding and combining minions in battle, pointing and sweeping them to attack enemies and solving puzzles to execute his dastardly plans. Controlling the Special Farces team of four, players negotiate fiendish levels and take on a huge range of warped enemies to hunt down the Kindred, a cult dedicated to resurrecting the mighty Dragon Kin, a race of humanoid dragon hybrids, determined to replace the Overlord''s despotism with their own. Extending the Overlord series'' trademark humour, gameplay focuses on the mischievous physical comedy of the minion''s antics and is delivered in a stylised cartoon visual style.' FROM games WHERE igdb_id = 48 ON CONFLICT (game_id, language_code) DO NOTHING;
