INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Mystery Dungeon: Explorers of Sky', 'Embark on a journey after you get turned into a Pokémon as a result of a freak accident, causing you to lose your memory as well as contact with and knowledge of your previous adventuring partner, with whom you were on a secret mission to save the world. Watch your story unfold in a dungeon crawling rogue-lite experience as you form your very own rescue team with a new partner of your choosing.' FROM games WHERE igdb_id = 2323 ON CONFLICT (game_id, language_code) DO NOTHING;
