INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Naruto Shippuden: Ninja Destiny 2', 'Naruto Shippuden: Ninja Destiny 2 features fast paced Naruto Shippuden 3D fighting action with the addition of an all-new Quest Mode, new characters, jutsu and a storyline based on the Naruto Shippuden animated series. The title also features wireless multiplayer gameplay, offering Naruto fans and newcomers to the series competitive 3D fighting on the Nintendo DS.' FROM games WHERE igdb_id = 47935 ON CONFLICT (game_id, language_code) DO NOTHING;
