INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('colin-mcrae-dirt-2', 561, '2009-09-08', 79, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2hnp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/l0lkf75ityzbwcot1mpd.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Colin McRae: Dirt 2', 'As the sequel to the acclaimed racer of 2007, DiRT 2 is set to take off-road racing games to a new level, with benchmark tech, thrilling new race types, big event atmosphere, stunning locations, a new breed of off-roading heroes and a peerless line-up of super-charged speed machines. Promising a thrilling race experience and an extreme sports attitude that borrows from snowboarding and skateboarding culture, DiRT 2 will take players on a World Tour to diverse and challenging real-world environments to compete in contemporary off-road events. Specifically selected to deliver aggressive and fast paced racing, DiRT 2''s garage will house a best-in-class collection of officially licensed rally cars and off-road vehicles; covering seven vehicle classes and players will be given the keys to powerful machines right from the off.' FROM games WHERE igdb_id = 561 ON CONFLICT (game_id, language_code) DO NOTHING;
