INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jurassic-the-hunted', 4946, '2009-11-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2zfy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9gxn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jurassic: The Hunted', 'Jurassic: The Hunted is a fast-paced first-person shooter that sends players back through time, to pit them against the monstrous creatures that ruled the title era. Survival itself is the greatest measure of success, as the player is challenged to outgun and outsmart aggressive oversized enemies such as raptors, Triceratops, and Tyrannosaurus. Various game modes have players scavenging the prehistoric environment for useful weapons and equipment, defending makeshift fortifications under siege, and in all-out boss battles and arena fights against giant, ferocious opponents. A bullet-time styled "adrenaline burst" feature allows players to slow the action down during key sequences, for a one-time chance to take careful aim at a dinosaur enemy''s most vulnerable points. The budget-friendly game puts players in the role of expert survivalist Craig Dylan, who has been hired to help protect a team of researchers investigating a temporal distortion on a heretofore-unknown island. When Dylan is mysteriously pulled backward through time to the era of the dinosaurs, he has only his wits and his weapon skills to keep him from becoming some terrible lizard''s lunch.' FROM games WHERE igdb_id = 4946 ON CONFLICT (game_id, language_code) DO NOTHING;
