INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MX vs. ATV: Reflex', 'Think fast and hang on to your ride as you take independent control of the rider and take the ultimate test of mettle. Dual controls let you tear it up with death-defying tricks and high-flying freestyle action. Fight for traction and dig up the track to leave your mark.' FROM games WHERE igdb_id = 7091 ON CONFLICT (game_id, language_code) DO NOTHING;
