INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Black Sigil: Blade of the Exiled', 'Bel Lenora is a world where people are born with magic at their command. Years ago, a single man walked the land with no magic in his veins. He brought death and tragedy in his wake and was banished by a brave General at a great cost. It has been fifteen years since his banishment and once again, a young man with no magic walks the land of Bel Lenora. Join Kairu, a young knight, born with a cursed spirit...' FROM games WHERE igdb_id = 21124 ON CONFLICT (game_id, language_code) DO NOTHING;
