INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nancy Drew: The Haunting of Castle Malloy', 'Touted as the most romantic event to grace the ruined halls of Ireland''s Castle Malloy, the Simmons-Mallory wedding was supposed to be a fairytale beginning, but now the groom is missing! Did a banshee crash the wedding or is this a case of cold feet? Can you, as Nancy Drew, unravel the knot of scattered clues and scary superstitions? You''ll to catch more than a bridal bouquet to make this is a happily ever after!' FROM games WHERE igdb_id = 16002 ON CONFLICT (game_id, language_code) DO NOTHING;
