INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Professor Layton and the Last Specter', 'Last Specter is the fourth game in the Professor Layton series, and is a prequel that takes place three years before the first trilogy, detailing how Professor Layton met his apprentice, Luke Triton. The game includes over 170 puzzles. Professor Layton and the Last Specter also includes an additional role-playing game entitled Professor Layton''s London Life, available from the start of the game. London Life, in which players interact with various characters from the series in a town called "Little London", was advertised to contain over 100 hours of content. London Life was removed from the European versions of the game in order to prevent a significant delay of the game''s release for translation.' FROM games WHERE igdb_id = 1400 ON CONFLICT (game_id, language_code) DO NOTHING;
