INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eduardo the Samurai Toaster', 'Battle wave after wave of enemies in this stylish side-scrolling run n'' gun action game for one to four players Fight your way through 13 diverse locations on your own or with up to three friends in this frenetic sidescrolling action game. Play as Eduardo and his fellow toaster buddies as you fire an assortment of pastries at all kinds of dastardly food products. Hop onto laser-mounted scooters and fly across the screen in rocket packs, and learn to cooperate with your teammates or simply annoy each other in an awesomely fun way by throwing each other around the screen. The choice is up to you.' FROM games WHERE igdb_id = 21193 ON CONFLICT (game_id, language_code) DO NOTHING;
