INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MLB 09: The Show', 'MLB 09: The Show is a baseball simulation video game developed by SCE San Diego Studio and published by Sony Computer Entertainment for the PlayStation 2, PlayStation 3, and PlayStation Portable systems. It belongs to the Major League Baseball game series on the PlayStation systems. MLB 09: The Show is the fourth edition of the MLB: The Show series. The game is a baseball simulation in which, depending on the gameplay mode, the player controls one or all of the players on a Major League Baseball team or some select Minor League Baseball teams. Depending on the gameplay mode, the player may control a team for a single game, season, or franchise, and can also create a player and control his career.' FROM games WHERE igdb_id = 7371 ON CONFLICT (game_id, language_code) DO NOTHING;
