INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu-Gi-Oh! 5D''s Tag Force 4', 'Based on the all-new Yu-Gi-Oh! 5D''s animated series, Yu-Gi-Oh! 5D''s Tagforce 4 reignites the story of the Dark Signers. The Dark Signers, derived from the Underworld, have been reborn with incredible abilities, a lust for revenge and a desire for complete power. The battle rages between good and evil for total domination of New Domino City and the fate of Satellite in story mode. Or battle opponents in one-on-one free duels or team up with a partner to defeat your opponents with more than 3,500 cards.' FROM games WHERE igdb_id = 42790 ON CONFLICT (game_id, language_code) DO NOTHING;
