INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Steins;Gate', 'Steins;Gate is a Japanese visual novel developed by 5pb. and Nitroplus. It is the second game in the Science Adventure series following Chaos;Head. The game is described by the development team as a "hypothetical science ADV" and explores time and time travel in 2010 Akihabara. The gameplay follows non-linear plot lines which offer branching scenarios with courses of interaction.' FROM games WHERE igdb_id = 7194 ON CONFLICT (game_id, language_code) DO NOTHING;
