INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('brave-a-warrior-s-tale', 4729, '2009-08-04', 43, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9pu5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/yalv2rumiycfupenn9g3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brave: A Warrior''s Tale', 'Set in a fantastic world based upon the mythology of Native America, Brave: A Warrior''s Tale plays as a series of flashbacks in which a now elderly Brave describes the events of his life. Between the warrior’s tales of his youth, the player takes control of Courage, a young boy who takes lessons from his elder''s experiences to stop the current threat to their village. The game provides players expansive exploration and in-game interactivity on their quest to defeat the sources of evil, continuously offering a significant challenge to players as they advance through a world of untamed wilderness. Brave is able to transform into various animals, track prey, and battle enemies that stand in his way with bows and arrows, tomahawks and a variety of ancient powers.' FROM games WHERE igdb_id = 4729 ON CONFLICT (game_id, language_code) DO NOTHING;
