INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Canabalt', 'Use your Parkour skills to outrun the destruction of your city with just one button! One of the most popular and best-loved Flash games of 2010, Canabalt was created in 5 days for the Experimental Gameplay Project, and features a rad soundtrack by superstar indie composer Daniel Baranowsky (Super Meat Boy).' FROM games WHERE igdb_id = 2270 ON CONFLICT (game_id, language_code) DO NOTHING;
