INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Big Brain Wolf', 'Big Brain Wolf is a hilarious point and click adventure game for puzzle lovers. The player takes upon the role of an asthmatic vegetarian wolf studying to become a genie. In the course of his adventures the player will encounter a large cast of famous funny characters and solve sixty different puzzles. Six neuroscientist designed highly replayable brain training exercises will earn the player precious hints to help solve the more difficult puzzles.' FROM games WHERE igdb_id = 14993 ON CONFLICT (game_id, language_code) DO NOTHING;
