INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Everyday Genius: SquareLogic', 'Everyday Genius: SquareLogic can calculate and display possible solutions automatically—allowing you to spend more time playing and less time tediously jotting down possibilities. With puzzles ranging from first-grade easy to astrophysicist hard, you’ll progress along the path to enlightenment as you build your problem-solving brain power with Everyday Genius: SquareLogic.' FROM games WHERE igdb_id = 16005 ON CONFLICT (game_id, language_code) DO NOTHING;
