INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Broken Sword: The Smoking Mirror - Remastered', 'Broken Sword: The Smoking Mirror - Remastered is a remastered edition of the original game. The game features the same basic story, but has additional features, including fully animated facial expressions, higher quality audio, an interactive comic book, cloud save support, context-sensitive hints, a game diary and a new user interface.' FROM games WHERE igdb_id = 27860 ON CONFLICT (game_id, language_code) DO NOTHING;
