INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Worms 2: Armageddon', 'Worms 2: Armageddon is a 2D artillery turn-based tactics video game developed by Team17 and part of the Worms series, released on July 1, 2009 on Xbox Live Arcade. The game is a follow up to the 2007 Worms game, which in-turn was a port of 2006''s Worms: Open Warfare.' FROM games WHERE igdb_id = 20480 ON CONFLICT (game_id, language_code) DO NOTHING;
