INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Company of Heroes: Tales of Valor', 'Company of Heroes: Tales of Valor is the expansion to the Game of the Year winner and highest rated real time strategy franchise Company of Heroes. Featuring new campaigns to overcome, units to command, and battlefields to conquer, Company of Heroes: Tales of Valor delivers evolved gameplay mechanics and 3 episodic adventures including 9 new missions, 3 new Multiplayer Modes, and new abilities to master.' FROM games WHERE igdb_id = 1371 ON CONFLICT (game_id, language_code) DO NOTHING;
