INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Forza Motorsport 3', 'Forza Motorsport 3 is a racing video game developed for Xbox 360 by Turn 10 Studios. It was released in October 2009. It is the sequel to Forza Motorsport 2 and the third installment in the Forza Motorsport series. The game includes more than 400 customizable cars (More than 500 cars in the Ultimate Collection version) from 50 manufacturers and more than 100 race track variations with the ability to race up to eight cars on track at a time. These cars vary from production cars to race cars such as those from the American Le Mans Series.[1]' FROM games WHERE igdb_id = 3069 ON CONFLICT (game_id, language_code) DO NOTHING;
