INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('endless-ocean-blue-world', 4833, '2009-09-17', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4cze.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/gulx5lgoo0nwyiz3kv8x.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Endless Ocean: Blue World', 'The ocean is teeming with life. Hundreds of real-life species are there to be discovered, from seahorses to giant whales. Are the local fish sick or agitated? Players can view their health status and then use a tranquilizer-like tool to zap the ones in need of rehab with healing energy. The game also includes a storyline that players can follow as they choose. The plot involves Oceana, a woman who investigates the ?Dragon?s Song,? which her father, a prominent ocean explorer, was searching for just before his death. While at Nine Ball Island, players can become friends with a dolphin and teach it some new tricks. When ona dive, players can even bring along the dolphin, which players can hold onto for extra fast swimming. For the first time in the series, friends who have broadband Internet access can connect and dive with one another via Nintendo Wi-Fi Connection, while using the Wii Speak? microphone to converse.' FROM games WHERE igdb_id = 4833 ON CONFLICT (game_id, language_code) DO NOTHING;
