INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Spy Spooky Mansion', 'Discover a thrilling I SPY adventure hidden in a mysterious old house! A clever skeleton traps you inside her spooky mansion with a challenge to find the secret way out. Explore each room of the house in first-person perspective to reveal over 30 I SPY riddles. Solve I SPY riddles, earn clues and play brain-teasing games to uncover the mansion’s secret escape!' FROM games WHERE igdb_id = 19844 ON CONFLICT (game_id, language_code) DO NOTHING;
