INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pro-evolution-soccer-2010', 4649, '2009-10-23', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3z3i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/d92yqdrixw5nwjrq6wcf.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Evolution Soccer 2010', 'Pro Evolution Soccer 2010 is the 2010 instalment of the yearly-released PES series. It introduced several improvements, including the official licensing of the Europa League (formerly the UEFA Cup). Other additions include a revamped penalty system, enhanced visuals, more distinct player characteristics, new animations, and the return of Community Mode. Network mode features lag-free matches, provided the connection is stable. The cover features Lionel Messi and Fernando Torres, and the game serves as the successor to PES 2009. Many fans viewed this edition as an opportunity for the series to reclaim the title of best football simulator, which had been lost to the FIFA series two years prior. A demo was released on September 17, with the full game launching on October 23, placing it in direct competition with the FIFA series.' FROM games WHERE igdb_id = 4649 ON CONFLICT (game_id, language_code) DO NOTHING;
