INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sbk-09-superbike-world-championship--1', 7179, '2009-05-29', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co72ey.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qivtanw99op33j8lqbd8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SBK 09: Superbike World Championship', 'The Superbike World Championship comes back to life in SBK09: the teams, the riders, the bikes and the tracks of the world''s most thrilling motorbike competition. All the aspects of the Championship have been faithfully reproduced in each aspect of the game: the menu graphics and the TV cameras, the pit, the paddock show, the starting grid and the fascinating "umbrella girls" will contribute to make the gaming experience as involving as possible. Thanks to a series of options it''s possible to make the game more faithful to the real thing or easier and more accessible, based on one''s preferences. After selecting the preferred riding style between Basic, Arcade, Advanced, Simulation and Extreme, it''s possible to adapt the game to each own needs: braking assistance, power braking, front and rear braking at once or separate control, traction control, advanced physics, off track stability control, rider''s health, bike damages, tire wear, starting help, automatic transmission, rider position control, official rules, warm up lap, false start penalty, ideal trajectory, riding help. When selecting the Simulation riding model there are many things that need to be taken into consideration: tires wear down, brakes can wear down, the bike can be damaged and the rider can be injured when an accident occurs. It''s therefore important to find the best setup for the bike changing suspension setup, handling geometry, braking, chainring length, gear ratio and tire type.' FROM games WHERE igdb_id = 7179 ON CONFLICT (game_id, language_code) DO NOTHING;
