INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Avernum 6', 'Avernum is one of the great tales of indie gaming, an epic series of fantasy role-playing adventurers set in an enormous, subterranean nation. Avernum is a land underground, a subterranean nation full of rogues, misfits, and brigands, struggling for survival and wealth in the monster-infested darkness. Avernum 6 is the final chapter in the Great Trials Trilogy, three games that tell the tale of your weary land’s final destiny.' FROM games WHERE igdb_id = 16339 ON CONFLICT (game_id, language_code) DO NOTHING;
