INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Osmos', 'Enter the ambient world of Osmos: elegant, physics-based gameplay, dreamlike visuals, and a minimalist, electronic soundtrack. Your objective is to grow by absorbing other motes. Propel yourself by ejecting matter behind you. But be wise: ejecting matter also shrinks you. Relax - good things come to those who wait.' FROM games WHERE igdb_id = 14951 ON CONFLICT (game_id, language_code) DO NOTHING;
