INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nyxquest-kindred-spirits', 10262, '2009-06-19', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3q9w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arqpk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NyxQuest: Kindred Spirits', 'Fly with Nyx in her dangerous search for her dearest friend Icarus. With NYXQUEST: KINDRED SPIRITS you will discover a new type of game play and mechanics that will surprise you... The action takes place in ancient Greece, a place inhabited by all kind of fantastic creatures, where the fate of humans is in the hands of capricious Gods. Through impressive sceneries, you will guide Nyx in her icarian quest, and will enjoy the ultimate experience: the joy of flight! But be careful! These surroundings are dangerous for celestial beings. Without your help she will not be able to complete her task. Protect and guide her flight, and take advantage of the incredible powers that gods such as Zeus or Eolus will grant…if you figure out how to reach them!' FROM games WHERE igdb_id = 10262 ON CONFLICT (game_id, language_code) DO NOTHING;
