INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Emerald City Confidential', 'Work with the world''s most cunning detective in the shadowy underbelly of the Emerald City of Oz! As Petra, you''ll be lured deep into mysteries involving new foes and familiar faces; Scarecrow, Lion, and Toto included. This is Oz as you''ve never seen it before! Solve your detective''s quest and unravel a conspiracy of magic and intrigue! Follow a case through five chapters full of puzzles, witnesses, suspects, and allies.' FROM games WHERE igdb_id = 16072 ON CONFLICT (game_id, language_code) DO NOTHING;
