INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ski-Doo: Snowmobile Challenge', 'Ski-Doo Snowmobile Challenge is a snowmobile racing game and a follow up to the PlayStation 2 game Ski-Doo Snow X Racing. The game is similar to its predecessor but has a larger number of tracks, with 25 different events taking place in five different countries: Canada, Russia, Sweden, USA and Norway. There are four different types of events: cross country, snowcross, hill cross and freestyle. Like other extreme sports games doing tricks is a central part of the game.' FROM games WHERE igdb_id = 5158 ON CONFLICT (game_id, language_code) DO NOTHING;
