INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Light of Altair', 'Light of Altair is a sci-fi colony building game with a deep plot. Grow colonies from landing pod to metropolis, while sending off new spaceships to expand your territory to other worlds. You are not alone in space, 8 factions from different parts of the world are all following their own agendas in the solar system; diplomacy and orbital-combat are essential to learn.' FROM games WHERE igdb_id = 16041 ON CONFLICT (game_id, language_code) DO NOTHING;
