INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reksio: Miasto Sekretów', 'Reksio: Miasto Sekretów is the very first version of the game known worldwide as City of Secrets. This release was made only in Poland, Romania and Russia. In this edition players may experience elements removed in later versions, such as references to the first game series "Rex''s Adventures", labyrinth mini-games, and the soundtrack derived from the first series.' FROM games WHERE igdb_id = 146300 ON CONFLICT (game_id, language_code) DO NOTHING;
