INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('two-worlds-epic-edition', 27841, '2009-04-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co220t.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arsdb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Two Worlds: Epic Edition', 'At the beginning of your epic adventure, a mercenary task takes you to the far north - but you''re also following up a mysterious lead at the same time - the first clue you''ve been given since Kyra''s disappearance. You get a shock during a meeting with the delegates of a dark Brotherhood - your sister''s kidnappers are indeed after your family''s relict. Whether there''s any truth in your family being chosen ones or not, the others obviously believe it - and if you ever want to see Kyra alive again, you''ll have to act swiftly...' FROM games WHERE igdb_id = 27841 ON CONFLICT (game_id, language_code) DO NOTHING;
