INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Foreign Legion: Buckets of Blood', 'Foreign Legion: Buckets of Blood is a cartoon-style third-person shooter. You take the role of a last-standing hard-boiled Legionnaire taking on an entire rebel army. A small campaign with various objectives, such as defending civilians, escorting a tourist bus and a mass-chicken-murder map. The game includes a ranking system that allows you to unlock new outfits, accessories and of course new weapons.' FROM games WHERE igdb_id = 7521 ON CONFLICT (game_id, language_code) DO NOTHING;
