INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fallen Earth', 'It’s 2156, and the world has been destroyed by both nuclear and bio-chemical means. Your story takes place in one of the few habitable places left in the world, the Grand Canyon. As a clone with an uncertain past, your job is survival in a world now built on destruction, betrayal and fragile factional alliances.' FROM games WHERE igdb_id = 15150 ON CONFLICT (game_id, language_code) DO NOTHING;
