INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('crystal-defenders-r2', 21133, '2009-02-24', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5hc6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/kj3w1nc4izsk8e3ocmhm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crystal Defenders R2', 'In a land ruled by might and magic, peace is ensured by the benevolent power of the crystals. In CRYSTAL DEFENDERS R2, you must deploy various units, such as Fencers and Black Mages, to stop waves of encroaching monsters from escaping the area with your party''s crystals. There are many types of units to choose from: some specializing in powerful short-range attacks, some wielding far-reaching magicks, and still others equipped with bows, enabling them to bring down aerial foes. Deploy units in strategic locations to take full advantage of their traits. Each time an enemy breaches your defenses and reaches a map''s exit, your party will lose crystals. When all your crystals are gone, the game is over. R2 offers several new, challenging maps containing multiple entrances and exits. It also introduces three varieties of Power Crystals, allowing you to enhance the abilities of your units, while new jobs, including Flintlock and Tinker, set the stage for even more complex strategies. Can you defend all the maps without losing a single crystal?' FROM games WHERE igdb_id = 21133 ON CONFLICT (game_id, language_code) DO NOTHING;
