INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hidden Mysteries: Titanic', 'Titanic: The Game takes place aboard the R.M.S. Titanic on her fateful maiden voyage across the Atlantic. The player’s avatar is a young socialite, Margaret Ashley, one of the fortunate unfortunates who sailed on Titanic and survived. Throughout the course of the game, Margaret is presented with sets of puzzles and obstacles that she must overcome to progress the timeline from April 10th - the date Titanic left Southampton Dock – to the 15th, when she sunk beneath the waves.' FROM games WHERE igdb_id = 35257 ON CONFLICT (game_id, language_code) DO NOTHING;
