INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('men-of-war', 9854, '2009-02-27', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co255z.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar22lb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Men of War', 'Men of War takes place in Europe and North Africa during the height of World War II. The story takes place over three different campaigns and players take on the role of Soviet, Allied and German soldiers. Each campaign has its own scenario and structured timeline, which brings different elements of the war to life. The game features hundreds of accurately modelled historical tanks and vehicles — including new designs of tanks, APCs and heavy guns — all of which are ready for your command. Dynamic in-game cutscenes enhance the single-player by telling the plot, without pulling the player out of the game experience. What''s more, the sounds of war have been given a new lease of life, with more than 1,000 sounds effects of weapons and combat gear; all recorded under real operating conditions. The single-player campaign also features a customisable user-interface, so players can have the command controls laid out in their own style. One of the biggest changes for Men of War is the inclusion of a comprehensive multiplayer, featuring new maps and modes, including Capture the Flag, High-Value Cargo and more. Also, there''s a refined rating system to ensure a fair fight in online multiplayer battles.' FROM games WHERE igdb_id = 9854 ON CONFLICT (game_id, language_code) DO NOTHING;
