INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wwe-legends-of-wrestlemania', 7488, '2009-03-19', 72, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co988v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/hnlslrxab2vad8coukjp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WWE Legends of WrestleMania', 'WWE Legends of WrestleMania embraces the leading sports entertainment organization''s rich history to relive, rewrite or recreate the definitive elements of WWE from the Eighties and Nineties. Players relive the entertaining lives of more than 40 larger-than-life Legends and have control over Legendary Managers, each of whom play crucial roles in match outcomes. The game''s new grapple-based fighting system captures the high-energy action and drama seen in vintage WWE matches, while a historically accurate representation of past WWE telecasts sets the stage, including dynamic visual treatments, signature ring entrances, renowned commentators and notable venues. WWE Legends of WrestleMania also includes a WrestleMania Tour Mode that allows players to participate in key matches from multiple WrestleMania events, a Create-A-Legend system to develop the Legends of tomorrow, as well as online functionality for players to compete on the biggest stages in WWE history.' FROM games WHERE igdb_id = 7488 ON CONFLICT (game_id, language_code) DO NOTHING;
