INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Torchlight', 'In this ARPG you control a hero who explores a series of randomized dungeons, fightinghordes of enemies and collecting equipment, gold, and loot while doing so. The game also features a town , to which the hero can return to sell and buy gear and items and pick up quests. As you progress into the dungeon, you get to battle unique bosses that advance the main storyline by completing quests revolving around them. Optionally, the player may take on side quests, random quests or visit branching dungeon areas to further develop their character.' FROM games WHERE igdb_id = 2480 ON CONFLICT (game_id, language_code) DO NOTHING;
