INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('brutal-legend', 212, '2009-10-13', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co27c8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4gq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brütal Legend', 'Brütal Legend is an action-adventure that marries visceral action combat with open-world freedom. Set in a universe somewhere between Lord of the Rings and Spinal Tap, it’s a fresh take on the action/driving genre, which in this case is full of imitation cover bands, demons intent on enslaving humanity and Heavy metal tunes. Featuring the talents of comedian, actor and musician, Jack Black as super roadie Eddie Riggs, as well as cameos by some of the biggest names in metal music it''s a wild ride in the belly of the beast that is not to be missed by gamers and Metalheads alike.' FROM games WHERE igdb_id = 212 ON CONFLICT (game_id, language_code) DO NOTHING;
