INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sea Dogs: City of Abandoned Ships', 'Fortune and glory awaits you! In Sea Dogs - City of Abandoned Ships you can choose to go it alone and become the most feared pirate of the seven seas. Or you can prove your loyalty to one of four different navies; French, English, Spanish, or Dutch. Sail the high seas as a swashbuckling pirate or dashing naval captain.' FROM games WHERE igdb_id = 51867 ON CONFLICT (game_id, language_code) DO NOTHING;
