INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drawn: The Painted Tower', 'Enter the world of Drawn, and unravel the secrets of the Painted Tower. Overcome challenging puzzles on your quest to save Iris. A curse has locked each floor of the tower, and only the most creative adventurer can find a way through. Enter lush painted worlds and meet fantastic characters who will help you…and sometimes try to stop you, on your quest through the dream world of The Painted Tower. Beware! Darkness approaches the tower. Can you save her in time?' FROM games WHERE igdb_id = 11234 ON CONFLICT (game_id, language_code) DO NOTHING;
