INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('aaaaaaaaaaaaaaaaaaaaaaaaa-a-reckless-disregard-for-gravity', 6286, '2009-09-03', 90, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3kxs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arny9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AaaaaAAaaaAAAaaAAAAaAAAAA!!!: A Reckless Disregard for Gravity', 'BASE jump through a floating city, creating your own stunts to delight your fans. You dive off a skyscraper, relying on quick reflexes to negotiate the intricate tangle of girders that make up the floating city. All eyes are on you as the judges mark your score. One hundred points for hugging those exposed struts as you fall. A thousand for planting a kiss on the side of that building. Twisting and turning, you thread the needle between two billboards, earning cheers from your fans. But while reflexes are important, it''s quick thinking that gets you the win. One block away, you spot a crowd of protesters decrying your sport, and make a split second decision. You break off course, stare them straight in the eye, and flip them the finger. They explode into a burst of fury, but the judges absolutely love it, bumping you up to first place. Now all you have to do is to make that landing without ending up a loose sack of broken bones.' FROM games WHERE igdb_id = 6286 ON CONFLICT (game_id, language_code) DO NOTHING;
