INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Theatre of War 2: Africa 1943', 'Theatre of War 2: Africa 1943 covers the events of 1943 in Tunisia, North Africa. Recovering from their losses after the crushing defeat and subsequent retreat after the Second Battle of El-Alamein, the German Afrika Korps - reinforced and now supported by the Italian Army - prepare once more to put steel against steel with the Allies.' FROM games WHERE igdb_id = 9858 ON CONFLICT (game_id, language_code) DO NOTHING;
