INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vanguard Princess', 'Government experiments on a young girl triggered a cosmic shock wave that gifted many young girls with mystical powers. She re-emerges into the world and vows to destroy all of mankind in an act of revenge. A brave group of girls who embraced their powers head to the battlefield to confront her; not just for the sake of the world, but to pursue their own personal motives and dreams.' FROM games WHERE igdb_id = 9433 ON CONFLICT (game_id, language_code) DO NOTHING;
