INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King Arthur: The Role-Playing Wargame', 'Critically praised by reviewers and gamers alike, King Arthur was received as one of the biggest surprises to emerge on the gaming scene in 2010. Now the Fantasy/Roleplaying RTS returns in a sequel set to push the boundaries of the genre even further. Our story begins long after young Arthur pulled the enchanted sword out of the stone, united the war-torn land of Britannia, gathered the Knights of the Round Table and secured peace in Camelot aided by the might of the Holy Grail. Where legends normally end, King Arthur II begins on its own gruesome tale...' FROM games WHERE igdb_id = 2038 ON CONFLICT (game_id, language_code) DO NOTHING;
