INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Football Manager 2010', 'Football Manager 2010 (abbreviated to Football Manager 10 or FM10) is a football manager simulation video game. It was released on Microsoft Windows, Mac OS X and PlayStation Portable on 30 October 2009.[3] It is also available for digital download on Steam and iOS.[4] The game demo was released on 14 October 2009.[5][6] This is the first release in the series to be sold under the Football Manager name throughout the world. Previous North American (i.e., United States/Canada) versions were sold as Worldwide Soccer Manager.' FROM games WHERE igdb_id = 716 ON CONFLICT (game_id, language_code) DO NOTHING;
