INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('star-wolves-3-civil-war', 9851, '2009-10-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co422o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar173u.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wolves 3: Civil War', 'Large-scale battles have become a vestige of the past, depleting resources of conflicting parties. Settled space, where welfare and order had reigned, has become a cemetery for dead ships which is flooded with pirates and adventurists. Complete impunity, black market flourishing where gun and tech trade is on the move, arbitrariness and anarchy – the Galaxy has become a real dangerous place. Events in the Universe and its habitant’s destiny are completely up to player’s choice and tactical decisions. Star Wolves 3: Civil War is a sequel to the popular real time strategy with RPG elements. Original large-scale scenario, closely tied with the first part of intergalactic epic helps the player influence the ongoing events and foreordain one of many endings. Free roam, free mission selection, free team forming – the world of Star Wolves waits for its heroes.' FROM games WHERE igdb_id = 9851 ON CONFLICT (game_id, language_code) DO NOTHING;
