INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('for-the-glory-a-europa-universalis-game', 2036, '2009-11-12', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3zuk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4j14.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'For The Glory: A Europa Universalis Game', 'Take up the reigns of your country, guide domestic and foreign policy, navigate thousands of historical events, engage in various struggles and lead your country to prosperity – all in the name of glory! For the Glory offers full historical immersion, with a completely new indepth experience with over 10000 historically accurate events. Take charge of the mighty Habsburg Empire, the aggressive Swedish state, or the seafaring Portuguese. Build up your empire through trade, diplomacy, colonialism and war. Interact with real historical events and persons to determine what path your nation will take. Nothing is written in stone, and while a wise leader may choose to follow the path of history, you may also take advantage of opportunities for change.' FROM games WHERE igdb_id = 2036 ON CONFLICT (game_id, language_code) DO NOTHING;
