INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cities XL: Platinum', 'Cities XL (formerly Cities Unlimited) is a city-building computer game developed by Monte Cristo, which has prior development experience in City Life. It was originally scheduled for release in the first quarter of 2009, but was eventually released on October 8, 2009. The game allowed players to play online and interact with others on massive persistent planets, and to work together by trading resources or building blueprints in order to satisfy the needs of city inhabitants. However, on March 8, 2010 the online service was closed and the game became single-player only.' FROM games WHERE igdb_id = 4214 ON CONFLICT (game_id, language_code) DO NOTHING;
