INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Race Pro', 'Race Pro is a sim racing video game described as having "ultra realistic car models" with cars ranging in power from 200 hp to 1,000 hp. The game features cars and drivers from the 2007, 2006 and the original 1987 FIA World Touring Car Championship seasons, as well as the European F3000, Formula BMW, Mini Challenge and Caterham cup. The game also has three GT categories, on top of this it has racing Radicals and road cars which are the Audi R8, Koenigsegg CCX, Koenigsegg CCXR and Dodge Viper.' FROM games WHERE igdb_id = 7151 ON CONFLICT (game_id, language_code) DO NOTHING;
