INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pocket-tanks-deluxe', 86841, '2009-04-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/yika5ewhlrypdrmj8eos.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/miavnz30qhvilv4l0ppk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pocket Tanks Deluxe', '"The Ultimate One-on-One Artillery Game" – Now with cross-platform WiFi and Online Play! Pocket Tanks is the fast-paced artillery game that is simple to learn, and fun to master. The perfect quick game for friends and family, you''ll find yourself hooked for hours of play! Bury your opponent in a mound of dirt, or assail him with a barrage of bullets. Visit the Weapon Shop before battle to arm yourself for the struggle, or try the Target Practice mode to learn all the weapons and the best tactics to win. Experience the thrill of launching volley after volley of powerful and fun weapons across the battlefield, using very simple controls. Select your angle, power, and FIRE! Your arsenal of unique and useful weapons includes: Napalm, Firecracker, Skipper, Cruiser, Dirt Mover, and dozens more! This is the light-hearted game of heavy artillery for everyone.
