INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('deadly-creatures', 4799, '2009-02-09', 61, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21yc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/idi6j5bo8re5vpyzxsqe.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deadly Creatures', 'Deadly Creatures allows players to play as a young male desert hairy scorpion and an adult female tarantula and engage in brutal combat against other arachnids, insects, rats, and reptiles. The two creatures have different playing styles, with the scorpion''s levels featuring more action-oriented gameplay, while the tarantula is more stealth oriented, with less linear levels. The Wii Remote and Nunchuk are used for both movement and attacks, with motion controls incorporated for special attacks and finishing moves, while the tarantula also utilizes the pointer function to shoot webs. New abilities are also gained as the player progresses through the game. Along with dispatching common arthropods such as pill bugs, crickets, beetles, and wolf spiders, most of which can be devoured to regain health, the player also faces bosses including a Gila Monster, a rattlesnake and eventually a human. The clashes between the creatures are described as similar to monster movies, with a similar impact to battles in King Kong and Jurassic Park albeit on a smaller scale.' FROM games WHERE igdb_id = 4799 ON CONFLICT (game_id, language_code) DO NOTHING;
