INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('winter-stars', 20155, '2009-11-09', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9k5y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/dmgraq40quyzl9dgq0qm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Winter Stars', 'Winter Stars, developed by 49 Games, entices gamers off their sofas with its high quality and easy-to-learn, exhilarating motion controls. The unique "family mode" allows each participant to choose his or her own individual difficulty level, thus making for a fun multiplayer experience with even chances for everyone. In single player mode, Winter Stars offers a campaign full of variety that allows players to experience all aspects of an athlete''s career. Winter Stars is a breath of fresh air for the genre, enabling sports fans of all ages and abilities to compete with one another or against virtual opponents in no less than eleven disciplines: snowmobiling, bobsledding, downhill skiing, figure skating, biathlon, free ride skiing, snowboard cross, ski jumping, paraskiing, curling, and short-track. In thrilling multiplayer action, up to four players can engage in dynamic online or offline competitions for championship titles, or simply enjoy the variety of winter sports themed mini-games on offer. The story-driven single player mode not only features an extensive career system and character development, but also a number of special challenges such as training sessions that provide arcade-style enjoyment in between events. Console athletes can use the experience points they earn to purchase new equipment and improve their skills in preparation for the diverse challenges ahead, and to support their team on its path to victory.' FROM games WHERE igdb_id = 20155 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 20155 AND ge.slug = 'sport' ON CONFLICT DO NOTHING;
