INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Dance Revolution Hottest Party 3', 'The gameplay of this game remains relatively unchanged from the original game. New modes on Dance Dance Revolution Hottest Party 3 include Tournament Mode, Relaxed Mode, DDR School, Hypermove Mode, and Wii Balance Board Modes. Returning modes include Free Play Mode and Training Mode. Dropped modes include the "Groove Circuit/Arena" Mode. It has been replaced with Tournament Mode. The use of hand markers have been removed from Free Play Mode. They are still existent in DDR School and Hypermove Mode, but are called Punch Markers.' FROM games WHERE igdb_id = 21782 ON CONFLICT (game_id, language_code) DO NOTHING;
