INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dead-mountaineers-hotel', 14851, '2009-11-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/t7ntomzeqjbdpqrg9kse.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/lmsefv6bstrtcdthhzsa.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Mountaineer''s Hotel', 'The remote hotel stands atop an ominous snow-peaked mountain, and death permeates every inch of the place. A crime has been committed here obviously, and the remote nature of the retreat means that the culprit is still roaming the halls. Which of the guests is capable of this? Whose past hides sinister truths and who has the most to gain? Secrets will not reveal themselves and skeletons will not stay buried. Dead Mountaineer’s Hotel will test all your detection skills as well as your ideas of right and wrong. The beautifully detailed, pre-rendered backgrounds provide the perfect backdrop to this twist of the traditional detective story. Do you have what it takes to unravel the threads behind this mysterious case, and where will your side be should your own feelings conflict with the law? Key features: Engaging storyline, with a non-linear plot that lets you make your choices. Over 120 gorgeous, pre-rendered locations. More than 15 3D character models featuring real-time shadows, each with their own original stories and unique personalities. AI simulation for all inhabitants of the gameworld to track their movements at all the times. Proprietary engine specifically developed for adventure games. 15+ hours of intriguing gameplay.' FROM games WHERE igdb_id = 14851 ON CONFLICT (game_id, language_code) DO NOTHING;
