INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grappling Hook', 'Grappling Hook is an innovative first-person action puzzle / platform game. You use the Grappling Hook as a mighty high-tech tool to overcome various challenging obstacles by performing incredible moves and fast combinations of daring tricks. The dynamic and surprising levels open opportunities to use the Grappling Hook in unique ways never seen before in a game. Making your way through the levels requires both skill and creativity, while the increasing difficulty pushes you to become a real master of the Grappling Hook.' FROM games WHERE igdb_id = 21106 ON CONFLICT (game_id, language_code) DO NOTHING;
