INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stoked: Big Air Edition', 'Stoked, which has the highest Metacritic score of any advanced-generation snowboarding game, is now faster, bigger, easier to control, and even more gorgeous in Stoked: Big Air Edition. New features include racing, marked trails that make it easy to find great runs, lots of park objects to use for tricks, two new mountains, better visuals, and faster and smoother riding.' FROM games WHERE igdb_id = 21107 ON CONFLICT (game_id, language_code) DO NOTHING;
