INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scene it? The Simpsons: Deluxe Edition', 'The First Family of Funny in a trivia game with The Simpsons TV clips! Celebrating the 20th anniversary of TV''s longest-running comedy, Scene It? The Simpsons Deluxe Edition is loaded with clips, on-screen puzzles and trivia from the first 20 seasons of the show! Show what you know about Homer, Marge, Bart, Lisa, Maggie and the rest of the citizens of Springfield.' FROM games WHERE igdb_id = 23789 ON CONFLICT (game_id, language_code) DO NOTHING;
