INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Roogoo Attack!', 'Based on the Xbox Live Arcade game Roogoo. Roogoo Attack! is a puzzle game emphasizing quick reflexes. This DS incarnation includes over 100 levels in 10 unique environments. More levels are unlocked by connecting with Roogoo Twisted Towers on the Wii. Single and multi-card multiplayer supports four players.' FROM games WHERE igdb_id = 21242 ON CONFLICT (game_id, language_code) DO NOTHING;
