INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('backbreaker', 5496, '2009-09-29', 57, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4k6j.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/tbylhuubwluie4dei8qa.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Backbreaker', 'Backbreaker is an American football video game, developed by British technology developer NaturalMotion, and released on 1 June 2010 in North America and on 25 June 2010 in Europe. One of its highlights is the use of Euphoria, a game animation engine that determines animations dynamically rather than depending on canned animations. Backbreaker does not use teams from the National Football League (NFL) because Electronic Arts has an exclusive license to produce NFL games in its Madden series. The game relies on an extensive logo editor and team builder that was called "one of its silver linings". NaturalMotion announced Backbreaker in August 2007, with a targeted release date of late 2008. The game ended up being delayed until mid-2010. Backbreaker received mixed reviews. While it was praised for the Euphoria animation system, realistic physical gameplay, and the logo editor, it was also criticized for its weak online play, poor passing game, and lack of depth in single-player modes. After the reviews, the passing game was adjusted by the greathouse patch. The Xbox 360 version of the game received an overall rating of 54% from review aggregator Metacritic, while the PlayStation 3 version received a 58%. The iOS and Android version was given a rating of 4.5 out of 5 stars by Touch Arcade. A patch released on 6 August 2010, alleviated many of the issues critics had with the game upon release and included upgrades such as: improved AI, new play books and an enhanced replay feature.[1]' FROM games WHERE igdb_id = 5496 ON CONFLICT (game_id, language_code) DO NOTHING;
