INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dot-flow', 24958, '2009-02-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2egs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/uat3296aoexlgbxsgnc1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '.Flow', '.Flow is one of the most well-known fangames of the original Yume Nikki, made by lol. It''s one of the darker spin-offs infamous for its eerie atmosphere and copious amounts of body horror and hospital imagery, centering around a girl named Sabitsuki (さびつき) as she enters her PC dreamworld to explore her mind and collect effects. .Flow is one of the more traditional fangames that stays true to the gameplay elements of the original. Effects are collected in a gloomy, sublime dreamscape and the user is left to interpret the events and lack of explicit storyline. The only differences that seem to set this game apart from Yume Nikki is the more concrete subject matter (the deeper aspects of the landscape seem to have a more pristine resemblance to human body parts, where as Nikki''s environment requires more interpretive thinking to analyze) and the inclusion of three endings instead of one. The main plot of the game is similar to the original Yume Nikki''s, in that it''s a sandbox game with very few exploration restrictions. You must collect the twenty-five effects to unlock two of the three endings and three boxes to achieve the third.' FROM games WHERE igdb_id = 24958 ON CONFLICT (game_id, language_code) DO NOTHING;
