INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teenage Mutant Ninja Turtles: Double Damage', 'Teenage Mutant Ninja Turtles: Double Damage is a 2009 online Flash game developed by Urban Squall as a promotional tool for Teenage Mutant Ninja Turtles Smash-Up. It is playable at many websites, including, as of 2010, the official Nickelodeon website. The game uses more 1987/2007-esque appearances for the Turtles, but most other characters take after their 2003 counterparts. Each Turtle has his advantages. Leonardo and Raphael are more effective in fighting Foot Ninja, while Donatello and Michelangelo are efficient in battling machines/robots. Leo and Don have long-range weapons, and Mike and Raph have stronger weapons.' FROM games WHERE igdb_id = 64244 ON CONFLICT (game_id, language_code) DO NOTHING;
