INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uncharted 2: Among Thieves - Limited Edition Collector''s Box', 'Uncharted 2: Among Thieves is the story of Nathan Drake, a fortune-hunter with a shady reputation and an even shadier past who is lured back into the treacherous world of thieves and mercenary treasure-seekers. Available in the EU only through GAME. The Collectors Box contains: - 2 Exclusive Art Cards - 2 Multiplayer Gold Plated Guns - 2 Exclusive Multiplayer Character Skins - Exclusive PS3 XMB Theme - Comes in Steekbook' FROM games WHERE igdb_id = 41882 ON CONFLICT (game_id, language_code) DO NOTHING;
