INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Buzz! Brain of the UK', 'Brace yourself United Kingdom Buzz is back, and he''s looking for the brightest quiz fans in the land! Brush up on your national knowledge and prepare to be tested on all the things that make the UK brilliant from movies and music to sport, celebs and much, much more! A portable quiz bonanza with over 4000 questions! Compete against friends on one PSP system in Pass Around mode or enjoy four player face-offs via Game Sharing Face 15 brain-busting rounds in the spectacular solo challenge' FROM games WHERE igdb_id = 21131 ON CONFLICT (game_id, language_code) DO NOTHING;
