INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Raven Squad: Operation Hidden Dagger', 'Raven Squad: Operation Hidden Dagger is a real time strategy and tactical first person shooter. It is developed by Atomic Motion and published by Evolved Games and SouthPeak Interactive. Raven Squad puts players in control of two groups of mercenary squads who have crash landed behind enemy lines in the Amazonian jungles. Each squad member has different skills which the player must use.' FROM games WHERE igdb_id = 7156 ON CONFLICT (game_id, language_code) DO NOTHING;
