INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ashes Cricket 2009', 'Ashes Cricket 2009, is a cricket video game developed by Transmission Games and published by Codemasters in the UK and by Atari in Australia. It has been released for the PlayStation 3, Xbox 360 and Microsoft Windows. A Wii version, developed by Gusto Games, has also been released. The Wii version was released simply as Cricket in Australia. A sequel, International Cricket 2010 was released on 18 June 2010. The game is licensed by the ECB (England and Wales Cricket Board), Cricket Australia and the Marylebone Cricket Club (MCC), owners of the Ashes Urn. It includes all the official players of the Australian cricket team and the England cricket team, however the other teams are not licensed.' FROM games WHERE igdb_id = 4680 ON CONFLICT (game_id, language_code) DO NOTHING;
