INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('csi-deadly-intent', 4780, '2009-10-20', 40, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2dci.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc80e3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CSI: Deadly Intent', 'In Sin City there are no secrets, only hidden answers. Join the new Vegas CSI team and explore five brand-new cases written by CSI writers. Explore crime scenes, examine victim’s bodies, and follow the surprising twists and turns of the story. Partner with the new cast of CSI Season 9 and team up with new characters such as Ray Langston (Laurence Fishburne) and Riley Adams (Lauren Lee Smith). Work as partners on the crime scene or help each other during tough suspect interrogations. Play as one of the most skillful forensic experts to join the Vegas CSI team. Help other detectives in their investigations and gain their respect through your actions and teamwork. Collect evidence at the crime scene by dusting for fingerprints, searching for valuable information, unveiling hidden evidence, and much more. Interview a variety of witnesses and suspects by asking key questions and using evidence to uncover the truth. Analyze evidence with a variety of new technology, such as DNA and microscope analysis.' FROM games WHERE igdb_id = 4780 ON CONFLICT (game_id, language_code) DO NOTHING;
