INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SingStar: Take That', 'SingStar: Take That is a karaoke game which exclusively features songs by the British pop band Take That. There are no changes to the gameplay formula: player(s) sing into a microphone and the game gives points based on the performance. The only basis of assessment is if the correct note is hit with the correct timing; the sung words or octave does not play into the result. The PS3 version allows access to the SingStore, an online shop for downloading additional songs.' FROM games WHERE igdb_id = 15193 ON CONFLICT (game_id, language_code) DO NOTHING;
