INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Where the Wild Things Are', 'Where the Wild Things Are is a fun-filled adventure that takes players on a journey through the mysterious island of the Wild Things. Players assume the role of Max, "King of All Wild Things," as they team up with the fearsome but loveable creatures. While journeying across their island, players learn amazing new skills and abilities. Solve action puzzles, overcome challenging obstacles, and play through a unique story narrative to uncover the mystery behind the hostile island and save the Wild Things before it''s too late!' FROM games WHERE igdb_id = 5278 ON CONFLICT (game_id, language_code) DO NOTHING;
