INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spore Hero Arena', 'An evil force is wreaking havoc across the galaxy, and only you can stop it! For the first time ever, build fully 3D Spore creatures on your Nintendo DS and take them into battle. Explore planets all over the galaxy, fight creatures, and gather parts to customize and enhance your mighty hero. Compete in a variety of arena battles against dangerous enemies in your quest to become the Galactic Champion and save the galaxy!' FROM games WHERE igdb_id = 21214 ON CONFLICT (game_id, language_code) DO NOTHING;
