INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '.Detuned', 'Developed by .theprodukkt, .detuned is a personalized, interactive music experience which gives you the opportunity to create dynamic artwork in real-time to accompany your XMB music collection. Manipulate the given scene by interacting with and modifying its unique graphics using the dual shock 3 Wireless Controller. Plus you can change and tweak your own music to accompany the scene. Download .detuned today for an artistic music experience.' FROM games WHERE igdb_id = 7724 ON CONFLICT (game_id, language_code) DO NOTHING;
