INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stoked', 'No paths, no boundaries, no limits. Drop out of a helicopter anywhere on the mountain. Dynamic weather makes riding different every time you play. Welcome to the backcountry. Welcome to Stoked. Featuring over 30 brands and eight pros including Travis Rice, Nicolas Mueller and more! Changing sun and snow conditions affect when, where, and how you ride. Bail out of ht helicopter anywhere on the mountain!' FROM games WHERE igdb_id = 7195 ON CONFLICT (game_id, language_code) DO NOTHING;
