INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'UFC 2009 Undisputed', 'UFC 2009 Undisputed is an explosive fighting game detailing the action, intensity and attitude of the Ultimate Fighting Championship (UFC). Featuring an authentic and comprehensive UFC atmosphere, including an extensive roster of the best mixed martial arts fighters in the world, players will push the envelope with a powerful new game engine and put their best fighting disciplines to the test in the world famous Octagon.' FROM games WHERE igdb_id = 7227 ON CONFLICT (game_id, language_code) DO NOTHING;
