INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Delaware St. John: Volume 1 - The Curse of Midnight Manor', 'Delaware St. John is able to see the extraordinary, and uses his gift to solve mysteries. One night, he ends up in the decrepit remains of an abandoned building, nicknamed Midnight Manor. Eerie voices call to Delaware, asking him to right the wrongs of their past. Delaware is not alone in the rotting building and will need your help in Delaware St. John: The Curse of Midnight Manor, a spooky Adventure game!' FROM games WHERE igdb_id = 73970 ON CONFLICT (game_id, language_code) DO NOTHING;
