INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SingStar: Motown', 'SingStar: Motown is a karaoke game which includes, with few exceptions, classic Motown songs from the 1960s and 1970s. There are no changes to the gameplay formula: player(s) sing into a microphone and the game gives points based on the performance.' FROM games WHERE igdb_id = 15191 ON CONFLICT (game_id, language_code) DO NOTHING;
