INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rock Band Unplugged', 'Rock Band Unplugged is an expansion of the Rock Band series of music video games. Game modes are similar to Rock Band''s, and the soundtrack includes a number of songs that have already been a part of the Rock Band series. Additional tracks will be a time-limited exclusive to Unplugged before they are released as downloadable content for the console games.' FROM games WHERE igdb_id = 2721 ON CONFLICT (game_id, language_code) DO NOTHING;
