INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shin-megami-tensei-strange-journey', 15467, '2009-10-08', 87, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co26fw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/mq7moenvlgnqyclhdsw0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shin Megami Tensei: Strange Journey', 'In the near future, a mysterious, growing, black void appears at the Earth''s southern pole. Unable to determine its cause and powerless to stop its deadly encroachment, humanity sends an elite team of explorers into the heart of the phenomenon, just as Strange Journey''s look and feel represent a return to the heart of Shin Megami Tensei, bringing to mind the all-time classic Nocturne. With over 300 demons to bribe, coerce, and negotiate with to gain assistance in battle, Strange Journey is every bit the deep, rewarding RPG experience fans have come to expect from the SMT franchise, yet delivered with a fresh new sci-fi story that taps into mature themes of morality and introspection.' FROM games WHERE igdb_id = 15467 ON CONFLICT (game_id, language_code) DO NOTHING;
