INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guitar Hero: Smash Hits', 'Guitar Hero Smash Hits is the best of Guitar Hero music, now for the full band! Rock out to the most fun tracks from Guitar Hero, Guitar Hero II, Guitar Hero: Rock the 80''s, and Guitar Hero III: Legends of Rock, now for the full band. Using the controllers strum, drum, and belt out a collection of master tracks including Nirvana, Judas Priest, Slayer, Rage Against the Machine, Queen, and many more. Titled Guitar Hero Greatest Hits in Europe and Australia.' FROM games WHERE igdb_id = 2677 ON CONFLICT (game_id, language_code) DO NOTHING;
