INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fireboy and Watergirl in the Forest Temple', 'Fireboy and Watergirl in The Forest Temple is a cooperative platformer and the 1st entry in the Fireboy and Watergirl series. You navigate characters Fireboy and Watergirl - either alone or with a friend - through various puzzles. Fireboy can walk in lava, but not in water. Watergirl can walk in water, but not in lava. Turn levers, press buttons, push boxes, and more in a total of 32 levels.' FROM games WHERE igdb_id = 122941 ON CONFLICT (game_id, language_code) DO NOTHING;
