INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Conduit', 'As Washington D.C. is embroiled in chaos, Secret Service agent Michael Ford finds himself recruited by a mysterious organization known as The Trust, and is quickly caught up in a national crisis, an alien invasion and a web of conspiracies that date back hundreds of years. Now you must help him learn to use bizarre new weapons, battle deadly aliens, discover ancient secrets, and save the world... if you can figure out who you can trust...' FROM games WHERE igdb_id = 4769 ON CONFLICT (game_id, language_code) DO NOTHING;
