INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Bigs 2', 'The BIGS 2 is an arcade-style baseball game that is less focused on the intricate details of the game and more on the actual gameplay, proven by the inclusion of power-ups and turbos during gameplay. All 30 teams from MLB and their stadiums are included, as well as their player rosters. The Wii version of this game is controlled by flicking the Wii remote and Nunchuk. These motion controls include drumming the remote and nunchuk when trying to speed up and using the remote as a bat when hitting.' FROM games WHERE igdb_id = 4716 ON CONFLICT (game_id, language_code) DO NOTHING;
