INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dangerous High School Girls in Trouble!', 'Explore four beautiful game boards, dozens of character cards, and thousands of dialog cards (worn and aged from decades of neglect) which comprise the zany world of an American small town in the 1920s. Encounter nearly a hundred individual personalities. These denizens form the core culture of intolerance and repression your girls can overcome with wit, charm, and brazenness.' FROM games WHERE igdb_id = 15990 ON CONFLICT (game_id, language_code) DO NOTHING;
