INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flora''s Fruit Farm', 'Clementine Valley used to be the place to be! It was world renowned for its fantastic fruit trees lovingly tended to by Old Jim.  Unfortunately Jim has lost the energy to grow enough fruit to keep the locals happy, let alone attract the tourists Clementine Valley used to have.  Luckily for Jim, Flora’s kind gesture showed him that she has the spirit to continue his legacy and he gives her his Magic Gardening gloves...' FROM games WHERE igdb_id = 16047 ON CONFLICT (game_id, language_code) DO NOTHING;
