INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '15 Days', 'A three-man activist group has set out to make the world a better place by stealing famous pieces of art in the world''s most renowned museums, selling them to private collectors, and donating the money to charity.  Though hunted by police forces, the group manages to stage one successful coup after another - until one day a mysterious new client appears and the group finds itself in the middle of a political conspiracy.' FROM games WHERE igdb_id = 26208 ON CONFLICT (game_id, language_code) DO NOTHING;
